var passed = 0
var failed = 0

func test(_ name: String, _ block: () throws -> Bool) {
    do {
        if try block() {
            print("  ✅ \(name)")
            passed += 1
        } else {
            print("  ❌ \(name) - assertion failed")
            failed += 1
        }
