+        normalize_client_coordinates(-5.0, 150.0, 100.0, 100.0),
+        (0.0, 0.0)
+    );
+    assert_eq!(map_to_host_pixels(0.5, 0.25, 1920.0, 1080.0), (960.0, 270.0));
+}
+
+fn sample_configuration() -> StreamConfiguration {
+    StreamConfiguration {
+        width: 3440,
+        height: 1440,
+        bitrate: 9_000_000,
+        frames_per_second: 90,
+    }
+}
+
+#[test]
+fn every_control_payload_body_round_trips() {
+    assert_round_trip(&BitrateAdjust {
+        target_bitrate: -1_234_567,
+    });
+    assert_round_trip(&sample_configuration());
+    assert_round_trip(&StreamConfigurationRequest {
+        request_id: 42,
+        desired: sample_configuration(),
+    });
+    assert_round_trip(&StreamConfigurationResponse {
+        request_id: 42,
+        active: sample_configuration(),
+    });
+    assert_round_trip(&StreamConfigurationReject {
+        request_id: 7,
+        reason: StreamConfigurationErrorCode::UnsupportedDimensions,
+        message: "too large".into(),
+    });
+    assert_round_trip(&StreamConfigurationError {
+        request_id: 8,
+        error_code: StreamConfigurationErrorCode::InvalidRequest,
+        message: "bad request".into(),
+    });
+    assert_round_trip(&ClipboardSyncRequest {
+        request_id: 11,
+        direction: ClipboardSyncDirection::Bidirectional,
+        origin: ClipboardSyncOrigin::LocalPasteboard,
+    });
+    assert_round_trip(&ClipboardSyncUpdate {
+        request_id: 12,
+        direction: ClipboardSyncDirection::HostToClient,
+        origin: ClipboardSyncOrigin::RemotePasteboard,
+        text: "hello clipboard".into(),
+    });
+    assert_round_trip(&ClipboardSyncError {
+        request_id: 13,
+        direction: ClipboardSyncDirection::ClientToHost,
+        origin: ClipboardSyncOrigin::SyncedFromPeer,
+        error_code: 9,
+        message: "clipboard rejected".into(),
+    });
+}
+
+#[test]
+fn every_control_message_type_round_trips() {
+    let messages = [
+        ControlMessage::RequestKeyFrame,
+        ControlMessage::StartStream,
+        ControlMessage::StopStream,
+        ControlMessage::Disconnect,
+        ControlMessage::Ping,
+        ControlMessage::Pong,
+        ControlMessage::BitrateAdjust(BitrateAdjust {
+            target_bitrate: 8_000_000,
+        }),
+        ControlMessage::StreamConfigRequest(StreamConfigurationRequest {
+            request_id: 1,
+            desired: sample_configuration(),
+        }),
+        ControlMessage::StreamConfigResponse(StreamConfigurationResponse {
+            request_id: 1,
+            active: sample_configuration(),
+        }),
+        ControlMessage::StreamConfigReject(StreamConfigurationReject {
+            request_id: 1,
+            reason: StreamConfigurationErrorCode::RejectedByPeer,
+            message: "no".into(),
+        }),
+        ControlMessage::StreamConfigError(StreamConfigurationError {
+            request_id: 1,
+            error_code: StreamConfigurationErrorCode::UnsupportedFps,
+            message: "fps".into(),
+        }),
+        ControlMessage::ClipboardSyncRequest(ClipboardSyncRequest {
+            request_id: 2,
+            direction: ClipboardSyncDirection::Bidirectional,
+            origin: ClipboardSyncOrigin::LocalPasteboard,
+        }),
+        ControlMessage::ClipboardSyncUpdate(ClipboardSyncUpdate {
+            request_id: 2,
+            direction: ClipboardSyncDirection::HostToClient,
+            origin: ClipboardSyncOrigin::RemotePasteboard,
+            text: "hello".into(),
+        }),
+        ControlMessage::ClipboardSyncError(ClipboardSyncError {
+            request_id: 2,
+            direction: ClipboardSyncDirection::ClientToHost,
+            origin: ClipboardSyncOrigin::SyncedFromPeer,
+            error_code: 3,
+            message: "error".into(),
+        }),
+    ];
+
+    for (expected_type, message) in ControlMessageType::ALL.into_iter().zip(messages) {
+        assert_eq!(message.message_type(), expected_type);
+        assert_round_trip(&message);
+    }
+}
+
+#[test]
+fn control_payloads_match_little_endian_layouts() {
+    assert_eq!(
+        BitrateAdjust {
+            target_bitrate: -2,
+        }
+        .encode()
+        .unwrap(),
+        (-2_i32).to_le_bytes()
+    );
+    assert_eq!(
+        StreamConfigurationRequest {
+            request_id: 0x0102_0304,
+            desired: StreamConfiguration {
+                width: 1,
+                height: 2,
+                bitrate: 3,
+                frames_per_second: 4,
+            },
+        }
+        .encode()
+        .unwrap(),
+        [
+            0x04, 0x03, 0x02, 0x01, 1, 0, 0, 0, 2, 0, 0, 0, 3, 0, 0, 0, 4, 0,
+        ]
+    );
+}
+
+#[test]
+fn control_rejects_unknown_message_and_payload_enum_values() {
+    assert!(matches!(
+        ControlMessage::decode(&[0xff]),
+        Err(CodecError::UnknownControlMessageType(0xff))
+    ));
+
+    let mut request = ClipboardSyncRequest {
+        request_id: 1,
+        direction: ClipboardSyncDirection::Bidirectional,
+        origin: ClipboardSyncOrigin::LocalPasteboard,
+    }
+    .encode()
+    .unwrap();
+    request[4] = 0xff;
+    assert!(ClipboardSyncRequest::decode(&request).is_err());
+}
+
+#[test]
+fn clipboard_update_rejects_more_than_four_kib_utf8() {
+    let update = ClipboardSyncUpdate {
+        request_id: 1,
+        direction: ClipboardSyncDirection::HostToClient,
+        origin: ClipboardSyncOrigin::LocalPasteboard,
+        text: "a".repeat(MAX_CLIPBOARD_TEXT_BYTES + 1),
+    };
+    assert!(update.encode().is_err());
+}
+
+#[test]
+fn video_payloads_round_trip_and_enforce_caps() {
+    let header = FrameHeader {
+        frame_id: 999,
+        width: 3840,
+        height: 2160,
+        is_key_frame: true,
+        total_chunks: 12,
+        total_size: 500_000,
+    };
+    assert_round_trip(&header);
+    assert_eq!(header.encode().unwrap().len(), FrameHeader::SIZE);
+
+    let chunk = FrameChunk {
+        frame_id: 42,
+        chunk_index: 3,
+        data: vec![0xab; 1024],
+    };
+    assert_round_trip(&chunk);
+
+    let mut invalid = header.clone();
+    invalid.total_chunks = MAX_CHUNKS_PER_FRAME + 1;
+    assert!(invalid.encode().is_err());
+    invalid = header.clone();
+    invalid.total_size = MAX_FRAME_BYTES + 1;
+    assert!(invalid.encode().is_err());
+
+    let oversized_chunk = FrameChunk {
+        frame_id: 1,
+        chunk_index: 0,
+        data: vec![0; MAX_VIDEO_CHUNK_BYTES + 1],
+    };
+    assert!(oversized_chunk.encode().is_err());
+}
+
+#[test]
+fn cursor_and_audio_payloads_round_trip() {
+    let cursor = CursorUpdate {
+        x: 0.333,
+        y: 0.666,
+        cursor_type: 2,
+    };
+    assert_round_trip(&cursor);
+    assert_eq!(cursor.encode().unwrap().len(), CursorUpdate::SIZE);
+
+    let header = AudioFragmentHeader {
+        frame_id: 123,
+        fragment_index: 1,
+        fragment_count: 3,
+    };
+    assert_round_trip(&header);
+    let fragment = AudioFragment {
+        header,
+        data: vec![0x55; 512],
+    };
+    assert_round_trip(&fragment);
+}
+
+#[test]
+fn audio_fragment_rejects_invalid_index_count_and_data_length() {
+    for header in [
+        AudioFragmentHeader {
+            frame_id: 1,
+            fragment_index: 0,
+            fragment_count: 0,
+        },
+        AudioFragmentHeader {
+            frame_id: 1,
+            fragment_index: 2,
+            fragment_count: 2,
+        },
+    ] {
+        assert!(header.encode().is_err());
+    }
+
+    let oversized = AudioFragment {
+        header: AudioFragmentHeader {
+            frame_id: 1,
+            fragment_index: 0,
+            fragment_count: 1,
+        },
+        data: vec![0; MAX_AUDIO_FRAGMENT_BYTES + 1],
+    };
+    assert!(oversized.encode().is_err());
+}
+
+#[test]
+fn invalid_utf8_is_rejected() {
+    assert!(PairingRequest::decode(&[1, 0, 0xff]).is_err());
+}
+
+macro_rules! truncation_test {
+    ($name:ident, $ty:ty, $value:expr) => {
+        #[test]
+        fn $name() {
+            let value: $ty = $value;
+            let bytes = value.encode().expect("canonical value encodes");
+            assert!(!bytes.is_empty());
+            for cut in 0..bytes.len() {
+                let result = <$ty>::decode(&bytes[..cut]);
+                assert!(
+                    result.is_err(),
+                    "{} accepted truncation at {cut}/{}: {result:?}",
+                    stringify!($ty),
+                    bytes.len()
+                );
+            }
+        }
+    };
+}
+
+truncation_test!(truncated_packet_header, PacketHeader, PacketHeader::new(PacketType::Ping, 1, 2, 0));
+truncation_test!(truncated_handshake, Handshake, sample_handshake(Capabilities::all()));
+truncation_test!(truncated_pairing_request, PairingRequest, PairingRequest { name: "client".into() });
+truncation_test!(truncated_pairing_grant, PairingGrant, PairingGrant { pairing_id: "id".into(), host_name: "host".into(), key: [7; PAIRING_KEY_SIZE] });
+truncation_test!(truncated_pairing_reject, PairingReject, PairingReject { reason: PairingRejectReason::LockedOut });
+truncation_test!(truncated_input_event, InputEvent, InputEvent { event_type: InputEventType::KeyDown, x: 0.0, y: 0.0, key_code: 36, modifiers: Modifiers::COMMAND, scroll_dx: 0.0, scroll_dy: 0.0 });
+truncation_test!(truncated_bitrate_adjust, BitrateAdjust, BitrateAdjust { target_bitrate: 8_000_000 });
+truncation_test!(truncated_stream_configuration, StreamConfiguration, sample_configuration());
+truncation_test!(truncated_stream_configuration_request, StreamConfigurationRequest, StreamConfigurationRequest { request_id: 1, desired: sample_configuration() });
+truncation_test!(truncated_stream_configuration_response, StreamConfigurationResponse, StreamConfigurationResponse { request_id: 1, active: sample_configuration() });
+truncation_test!(truncated_stream_configuration_reject, StreamConfigurationReject, StreamConfigurationReject { request_id: 1, reason: StreamConfigurationErrorCode::RejectedByPeer, message: "no".into() });
+truncation_test!(truncated_stream_configuration_error, StreamConfigurationError, StreamConfigurationError { request_id: 1, error_code: StreamConfigurationErrorCode::InvalidRequest, message: "error".into() });
+truncation_test!(truncated_clipboard_sync_request, ClipboardSyncRequest, ClipboardSyncRequest { request_id: 1, direction: ClipboardSyncDirection::Bidirectional, origin: ClipboardSyncOrigin::LocalPasteboard });
+truncation_test!(truncated_clipboard_sync_update, ClipboardSyncUpdate, ClipboardSyncUpdate { request_id: 1, direction: ClipboardSyncDirection::HostToClient, origin: ClipboardSyncOrigin::RemotePasteboard, text: "hello".into() });
+truncation_test!(truncated_clipboard_sync_error, ClipboardSyncError, ClipboardSyncError { request_id: 1, direction: ClipboardSyncDirection::ClientToHost, origin: ClipboardSyncOrigin::SyncedFromPeer, error_code: 3, message: "error".into() });
+truncation_test!(truncated_control_message, ControlMessage, ControlMessage::ClipboardSyncUpdate(ClipboardSyncUpdate { request_id: 1, direction: ClipboardSyncDirection::HostToClient, origin: ClipboardSyncOrigin::RemotePasteboard, text: "hello".into() }));
+truncation_test!(truncated_frame_header, FrameHeader, FrameHeader { frame_id: 1, width: 1920, height: 1080, is_key_frame: true, total_chunks: 2, total_size: 1024 });
+truncation_test!(truncated_frame_chunk_header, FrameChunk, FrameChunk { frame_id: 1, chunk_index: 0, data: Vec::new() });
+truncation_test!(truncated_cursor_update, CursorUpdate, CursorUpdate { x: 0.5, y: 0.5, cursor_type: 0 });
+truncation_test!(truncated_audio_fragment_header, AudioFragmentHeader, AudioFragmentHeader { frame_id: 1, fragment_index: 0, fragment_count: 1 });
+truncation_test!(truncated_audio_fragment, AudioFragment, AudioFragment { header: AudioFragmentHeader { frame_id: 1, fragment_index: 0, fragment_count: 1 }, data: Vec::new() });

