use crate::CodecError;

pub(crate) struct Decoder<'a> {
    input: &'a [u8],
    offset: usize,
}

impl<'a> Decoder<'a> {
    pub(crate) fn new(input: &'a [u8]) -> Self {
        Self { input, offset: 0 }
    }

    pub(crate) fn remaining(&self) -> usize {
        self.input.len() - self.offset
    }

    pub(crate) fn finish(self, field: &'static str) -> Result<(), CodecError> {
        if self.remaining() == 0 {
            Ok(())
        } else {
            Err(CodecError::TrailingBytes {
                field,
                remaining: self.remaining(),
            })
        }
    }

    pub(crate) fn take(
        &mut self,
        length: usize,
        field: &'static str,
    ) -> Result<&'a [u8], CodecError> {
        if self.remaining() < length {
            return Err(CodecError::Truncated {
                field,
                needed: length,
                remaining: self.remaining(),
            });
        }
        let start = self.offset;
        self.offset += length;
        Ok(&self.input[start..self.offset])
    }

    pub(crate) fn take_remaining(&mut self) -> &'a [u8] {
        let remaining = &self.input[self.offset..];
        self.offset = self.input.len();
        remaining
    }

    pub(crate) fn u8(&mut self, field: &'static str) -> Result<u8, CodecError> {
        Ok(self.take(1, field)?[0])
    }

    pub(crate) fn u16(&mut self, field: &'static str) -> Result<u16, CodecError> {
        let bytes = self.take(2, field)?;
        Ok(u16::from_le_bytes([bytes[0], bytes[1]]))
    }

    pub(crate) fn u32(&mut self, field: &'static str) -> Result<u32, CodecError> {
        let bytes = self.take(4, field)?;
        Ok(u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    pub(crate) fn i32(&mut self, field: &'static str) -> Result<i32, CodecError> {
        let bytes = self.take(4, field)?;
        Ok(i32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    pub(crate) fn u64(&mut self, field: &'static str) -> Result<u64, CodecError> {
        let bytes = self.take(8, field)?;
        Ok(u64::from_le_bytes([
            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
        ]))
    }

    pub(crate) fn f32(&mut self, field: &'static str) -> Result<f32, CodecError> {
        Ok(f32::from_bits(self.u32(field)?))
    }

    pub(crate) fn utf8(
        &mut self,
        length: usize,
        field: &'static str,
    ) -> Result<String, CodecError> {
        let bytes = self.take(length, field)?;
        std::str::from_utf8(bytes)
            .map(str::to_owned)
            .map_err(|_| CodecError::InvalidUtf8 { field })
    }
}

pub(crate) fn checked_bytes<'a>(
    value: &'a str,
    field: &'static str,
    max: usize,
) -> Result<&'a [u8], CodecError> {
    let bytes = value.as_bytes();
    if bytes.len() > max {
        Err(CodecError::LengthLimit {
            field,
            actual: bytes.len(),
            max,
        })
    } else {
        Ok(bytes)
    }
}

pub(crate) fn push_u16(output: &mut Vec<u8>, value: u16) {
    output.extend_from_slice(&value.to_le_bytes());
}

pub(crate) fn push_u32(output: &mut Vec<u8>, value: u32) {
    output.extend_from_slice(&value.to_le_bytes());
}

pub(crate) fn push_i32(output: &mut Vec<u8>, value: i32) {
    output.extend_from_slice(&value.to_le_bytes());
}

pub(crate) fn push_u64(output: &mut Vec<u8>, value: u64) {
    output.extend_from_slice(&value.to_le_bytes());
}

pub(crate) fn push_f32(output: &mut Vec<u8>, value: f32) {
    push_u32(output, value.to_bits());
}

pub(crate) fn usize_to_u8(
    value: usize,
    field: &'static str,
) -> Result<u8, CodecError> {
    u8::try_from(value).map_err(|_| CodecError::LengthLimit {
        field,
        actual: value,
        max: u8::MAX as usize,
    })
}

pub(crate) fn usize_to_u16(
    value: usize,
    field: &'static str,
) -> Result<u16, CodecError> {
    u16::try_from(value).map_err(|_| CodecError::LengthLimit {
        field,
        actual: value,
        max: u16::MAX as usize,
    })
}

pub(crate) fn usize_to_u32(
    value: usize,
    field: &'static str,
) -> Result<u32, CodecError> {
    u32::try_from(value).map_err(|_| CodecError::LengthLimit {
        field,
        actual: value,
        max: u32::MAX as usize,
    })
}

use crate::{codec::Decoder, CodecError, WireCodec};

pub const MAGIC: u16 = 0xec1d;
pub const PROTOCOL_VERSION: u8 = 3;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PacketType {
    Handshake = 0,
    HandshakeAck = 1,
    FrameHeader = 2,
    FrameChunk = 3,
    CursorUpdate = 4,
    InputEvent = 5,
    Control = 6,
    Ping = 7,
    AudioFrame = 8,
    PairingRequest = 9,
    PairingGrant = 10,
    PairingReject = 11,
}

impl PacketType {
    pub const ALL: [Self; 12] = [
        Self::Handshake,
        Self::HandshakeAck,
        Self::FrameHeader,
        Self::FrameChunk,
        Self::CursorUpdate,
        Self::InputEvent,
        Self::Control,
        Self::Ping,
        Self::AudioFrame,
        Self::PairingRequest,
        Self::PairingGrant,
        Self::PairingReject,
    ];
}

impl TryFrom<u8> for PacketType {
    type Error = CodecError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0 => Ok(Self::Handshake),
            1 => Ok(Self::HandshakeAck),
            2 => Ok(Self::FrameHeader),
            3 => Ok(Self::FrameChunk),
            4 => Ok(Self::CursorUpdate),
            5 => Ok(Self::InputEvent),
            6 => Ok(Self::Control),
            7 => Ok(Self::Ping),
            8 => Ok(Self::AudioFrame),
            9 => Ok(Self::PairingRequest),
            10 => Ok(Self::PairingGrant),
            11 => Ok(Self::PairingReject),
            unknown => Err(CodecError::UnknownPacketType(unknown)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PacketHeader {
    pub packet_type: PacketType,
    pub sequence: u32,
    pub timestamp_ms: u32,
    pub flags: u8,
}

impl PacketHeader {
    pub const SIZE: usize = 12;

    pub const fn new(
        packet_type: PacketType,
        sequence: u32,
        timestamp_ms: u32,
        flags: u8,
    ) -> Self {
        Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        }
    }
}

impl WireCodec for PacketHeader {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let mut output = Vec::with_capacity(Self::SIZE);
        output.extend_from_slice(&MAGIC.to_le_bytes());
        output.push(self.packet_type as u8);
        output.extend_from_slice(&self.sequence.to_le_bytes());
        output.extend_from_slice(&self.timestamp_ms.to_le_bytes());
        output.push(self.flags);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let magic = decoder.u16("packet magic")?;
        if magic != MAGIC {
            return Err(CodecError::InvalidMagic { found: magic });
        }
        let packet_type = PacketType::try_from(decoder.u8("packet type")?)?;
        let sequence = decoder.u32("packet sequence")?;
        let timestamp_ms = decoder.u32("packet timestamp")?;
        let flags = decoder.u8("packet flags")?;
        decoder.finish("packet header")?;
        Ok(Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        })
    }
}

use crate::{codec::usize_to_u32, CodecError};

pub const MAX_TCP_FRAME_SIZE: usize = 16 * 1024 * 1024;

pub struct TcpFrameWriter;

impl TcpFrameWriter {
    pub fn encode(payload: &[u8]) -> Result<Vec<u8>, CodecError> {
        if payload.is_empty() || payload.len() > MAX_TCP_FRAME_SIZE {
            return Err(CodecError::InvalidFrameLength(
                u32::try_from(payload.len()).unwrap_or(u32::MAX),
            ));
        }
        let length = usize_to_u32(payload.len(), "TCP frame")?;
        let mut output = Vec::with_capacity(4 + payload.len());
        output.extend_from_slice(&length.to_le_bytes());
        output.extend_from_slice(payload);
        Ok(output)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TcpFrameEvent {
    Frame(Vec<u8>),
    DroppedInvalidLength(u32),
}

#[derive(Debug, Default)]
pub struct TcpFrameReader {
    buffer: Vec<u8>,
}

impl TcpFrameReader {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn buffered_len(&self) -> usize {
        self.buffer.len()
    }

    pub fn clear(&mut self) {
        self.buffer.clear();
    }

    pub fn push(&mut self, input: &[u8]) -> Vec<TcpFrameEvent> {
        self.buffer.extend_from_slice(input);
        let mut events = Vec::new();

        loop {
            if self.buffer.len() < 4 {
                break;
            }
            let length = u32::from_le_bytes([
                self.buffer[0],
                self.buffer[1],
                self.buffer[2],
                self.buffer[3],
            ]);
            if length == 0 || length as usize > MAX_TCP_FRAME_SIZE {
                self.buffer.clear();
                events.push(TcpFrameEvent::DroppedInvalidLength(length));
                break;
            }
            let frame_end = 4 + length as usize;
            if self.buffer.len() < frame_end {
                break;
            }
            let payload = self.buffer[4..frame_end].to_vec();
            self.buffer.drain(..frame_end);
            events.push(TcpFrameEvent::Frame(payload));
        }

        events
    }
}

