use std::ops::{BitOr, BitOrAssign};

use crate::{
    codec::{checked_bytes, push_f32, push_u16, push_u64, usize_to_u16, Decoder},
    CodecError, WireCodec, PROTOCOL_VERSION,
};

pub const MAX_HANDSHAKE_NAME_BYTES: usize = 1024;
pub const MAX_PAIRING_ID_BYTES: usize = 256;
pub const SESSION_SALT_SIZE: usize = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Capabilities(u64);

impl Capabilities {
    pub const STREAM_CONFIGURATION: Self = Self(1 << 0);
    pub const CLIPBOARD_SYNC: Self = Self(1 << 1);
    pub const TEXT_CLIPBOARD_SYNC: Self = Self(1 << 2);

    pub const fn empty() -> Self {
        Self(0)
    }

    pub const fn all() -> Self {
        Self(
            Self::STREAM_CONFIGURATION.0
                | Self::CLIPBOARD_SYNC.0
                | Self::TEXT_CLIPBOARD_SYNC.0,
        )
    }

    pub const fn from_bits_retain(bits: u64) -> Self {
        Self(bits)
    }

    pub const fn bits(self) -> u64 {
        self.0
    }

    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

impl BitOr for Capabilities {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        Self(self.0 | rhs.0)
    }
}

impl BitOrAssign for Capabilities {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Handshake {
    pub name: String,
    pub width: u16,
    pub height: u16,
    pub scale: f32,
    pub version: u8,
    pub capabilities: Capabilities,
    pub pairing_id: String,
    pub session_salt: [u8; SESSION_SALT_SIZE],
}

impl WireCodec for Handshake {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        if self.version != PROTOCOL_VERSION {
            return Err(CodecError::UnsupportedVersion(self.version));
        }
        let name = checked_bytes(&self.name, "handshake name", MAX_HANDSHAKE_NAME_BYTES)?;
        let pairing_id = checked_bytes(
            &self.pairing_id,
            "handshake pairing ID",
            MAX_PAIRING_ID_BYTES,
        )?;
        let mut output = Vec::with_capacity(37 + name.len() + pairing_id.len());
        push_u16(
            &mut output,
            usize_to_u16(name.len(), "handshake name")?,
        );
        output.extend_from_slice(name);
        push_u16(&mut output, self.width);
        push_u16(&mut output, self.height);
        push_f32(&mut output, self.scale);
        output.push(self.version);
        push_u64(&mut output, self.capabilities.bits());
        push_u16(
            &mut output,
            usize_to_u16(pairing_id.len(), "handshake pairing ID")?,
        );
        output.extend_from_slice(pairing_id);
        output.extend_from_slice(&self.session_salt);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let name_length = decoder.u16("handshake name length")? as usize;
        if name_length > MAX_HANDSHAKE_NAME_BYTES {
            return Err(CodecError::LengthLimit {
                field: "handshake name",
                actual: name_length,
                max: MAX_HANDSHAKE_NAME_BYTES,
            });
        }
        let name = decoder.utf8(name_length, "handshake name")?;
        let width = decoder.u16("handshake width")?;
        let height = decoder.u16("handshake height")?;
        let scale = decoder.f32("handshake scale")?;
        let version = decoder.u8("handshake version")?;
        if version != PROTOCOL_VERSION {
            return Err(CodecError::UnsupportedVersion(version));
        }
        let capabilities = Capabilities::from_bits_retain(decoder.u64("handshake capabilities")?);
        let pairing_id_length = decoder.u16("handshake pairing ID length")? as usize;
        if pairing_id_length > MAX_PAIRING_ID_BYTES {
            return Err(CodecError::LengthLimit {
                field: "handshake pairing ID",
                actual: pairing_id_length,
                max: MAX_PAIRING_ID_BYTES,
            });
        }
        let pairing_id = decoder.utf8(pairing_id_length, "handshake pairing ID")?;
        let salt = decoder.take(SESSION_SALT_SIZE, "handshake session salt")?;
        let mut session_salt = [0_u8; SESSION_SALT_SIZE];
        session_salt.copy_from_slice(salt);
        decoder.finish("handshake")?;
        Ok(Self {
            name,
            width,
            height,
            scale,
            version,
            capabilities,
            pairing_id,
            session_salt,
        })
    }
}

use crate::{
    codec::{checked_bytes, push_u16, usize_to_u16, usize_to_u8, Decoder},
    CodecError, WireCodec,
};

pub const MAX_PAIRING_NAME_BYTES: usize = 1024;
pub const PAIRING_KEY_SIZE: usize = 32;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PairingRequest {
    pub name: String,
}

impl WireCodec for PairingRequest {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let name = checked_bytes(&self.name, "pairing request name", MAX_PAIRING_NAME_BYTES)?;
        let mut output = Vec::with_capacity(2 + name.len());
        push_u16(
            &mut output,
            usize_to_u16(name.len(), "pairing request name")?,
        );
        output.extend_from_slice(name);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let length = decoder.u16("pairing request name length")? as usize;
        if length > MAX_PAIRING_NAME_BYTES {
            return Err(CodecError::LengthLimit {
                field: "pairing request name",
                actual: length,
                max: MAX_PAIRING_NAME_BYTES,
            });
        }
        let name = decoder.utf8(length, "pairing request name")?;
        decoder.finish("pairing request")?;
        Ok(Self { name })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PairingGrant {
    pub pairing_id: String,
    pub host_name: String,
    pub key: [u8; PAIRING_KEY_SIZE],
}

impl WireCodec for PairingGrant {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let pairing_id = checked_bytes(&self.pairing_id, "pairing grant ID", u8::MAX as usize)?;
        let host_name = checked_bytes(&self.host_name, "pairing grant host name", u16::MAX as usize)?;
        let mut output = Vec::with_capacity(4 + pairing_id.len() + host_name.len() + PAIRING_KEY_SIZE);
        output.push(usize_to_u8(pairing_id.len(), "pairing grant ID")?);
        output.extend_from_slice(pairing_id);
        push_u16(
            &mut output,
            usize_to_u16(host_name.len(), "pairing grant host name")?,
        );
        output.extend_from_slice(host_name);
        output.push(PAIRING_KEY_SIZE as u8);
        output.extend_from_slice(&self.key);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let pairing_id_length = decoder.u8("pairing grant ID length")? as usize;
        let pairing_id = decoder.utf8(pairing_id_length, "pairing grant ID")?;
        let host_name_length = decoder.u16("pairing grant host name length")? as usize;
        let host_name = decoder.utf8(host_name_length, "pairing grant host name")?;
        let key_length = decoder.u8("pairing key length")? as usize;
        if key_length != PAIRING_KEY_SIZE {
            return Err(CodecError::InvalidLength {
                field: "pairing key",
                actual: key_length,
                expected: PAIRING_KEY_SIZE,
            });
        }
        let key_bytes = decoder.take(key_length, "pairing key")?;
        let mut key = [0_u8; PAIRING_KEY_SIZE];
        key.copy_from_slice(key_bytes);
        decoder.finish("pairing grant")?;
        Ok(Self {
            pairing_id,
            host_name,
            key,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PairingRejectReason {
    DeniedByHost = 0,
    LockedOut = 1,
    PairingDisabled = 2,
}

impl PairingRejectReason {
    pub const ALL: [Self; 3] = [
        Self::DeniedByHost,
        Self::LockedOut,
        Self::PairingDisabled,
    ];
}

impl TryFrom<u8> for PairingRejectReason {
    type Error = CodecError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0 => Ok(Self::DeniedByHost),
            1 => Ok(Self::LockedOut),
            2 => Ok(Self::PairingDisabled),
            unknown => Err(CodecError::UnknownPairingRejectReason(unknown)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PairingReject {
    pub reason: PairingRejectReason,
}

impl WireCodec for PairingReject {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        Ok(vec![self.reason as u8])
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let reason = PairingRejectReason::try_from(decoder.u8("pairing reject reason")?)?;
        decoder.finish("pairing reject")?;
        Ok(Self { reason })
    }
}

