+fn decode_empty_control(body: &[u8], value: ControlMessage) -> Result<ControlMessage, CodecError> {
+    if body.is_empty() {
+        Ok(value)
+    } else {
+        Err(CodecError::TrailingBytes {
+            field: "empty control message",
+            remaining: body.len(),
+        })
+    }
